commands.command:
cat > /etc/nginx/conf.d/port-6500.conf <<'ANTRIEB_NGINX_EOF'
server {
    listen 6500 default_server;
    listen [::]:6500 default_server;
    server_name _;
    root /usr/share/nginx/html;
    index index.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
ANTRIEB_NGINX_EOF
